{"summary": "Fetch Outage Information", "description": "Retrieve details on ongoing or upcoming utility outages in the user's area.", "responses": {"200": {"description": "Success response with outage information.", "content": {"application/json": {"example": {"outages": [{"type": "electricity", "status": "Scheduled", "startTime": "2023-10-15T08:00:00Z", "endTime": "2023-10-15T12:00:00Z"}]}}}}}}

Endpoint: GET /bills/recent
Specification:
{"summary": "Retrieve Recent Bills", "description": "Fetch a list of the most recent billing statements and their respective payment statuses.", "responses": {"200": {"description": "Success response with a list of recent bills and payment statuses.", "content": {"application/json": {"example": {"bills": [{"billDate": "2023-09-01", "amount": 75.5, "status": "Paid"}, {"billDate": "2023-08-01", "amount": 80.7, "status": "Outstanding"}]}}}}}}

Endpoint: GET /distributed-resources
Specification:
{"summary": "Retrieve all distributed energy resources", "description": "Fetches detailed information about all connected distributed energy resources.", "responses": {"200": {"description": "A list of connected distributed energy resources.", "content": {"application/json": {"schema": {"type": "array", "items": {"$ref": "#/components/schemas/DistributedResource"}}}}}}}

Endpoint: GET /alerts
Specification:
{"summary": "Retrieve alerts", "description": "Fetch all configured alerts along with their current statuses.", "responses": {"200": {"description": "Alerts retrieved successfully", "content": {"application/json": {"schema": {"type": "array", "items": {"type": "object", "properties": {"alert_id": {"type": "string", "description": "The unique identifier of the alert."}, "type": {"type": "string", "description": "The type of alert."}, "status": {"type": "string", "description": "The current status of the alert (e.g., active, inactive)."}, "last_triggered": {"type": "string", "format": "date-time", "description": "The timestamp when the alert was last triggered."}}}}}}}}}

Endpoint: GET /energy-tips
Specification:
{"summary": "Retrieve Energy-Saving Tips", "description": "Get personalized energy-saving tips based on the user's past usage patterns.", "responses": {"200": {"description": "Success response with a set of tailored energy-saving tips.", "content": {"application/json": {"example": {"tips": ["Turn off lights when not in use.", "Use energy-efficient appliances.", "Adjust thermostat settings during non-peak hours."]}}}}}}

Endpoint: POST /alerts/setup
Specification:
{"summary": "Configure an alert", "description": "Set up a custom alert, such as for usage thresholds or performance monitoring.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"type": {"type": "string", "description": "The type of alert to configure (e.g., threshold, anomaly)."}, "threshold": {"type": "number", "description": "The threshold value for triggering the alert."}, "frequency": {"type": "string", "description": "The frequency of monitoring (e.g., daily, hourly)."}}, "required": ["type", "threshold", "frequency"]}}}}, "responses": {"201": {"description": "Alert configured successfully"}}}

Endpoint: GET /usage-history
Specification:
{"summary": "Retrieve Utility Consumption History", "description": "Request detailed consumption history data for the user's utility services over a specified period.", "parameters": [{"name": "startDate", "in": "query", "required": true, "description": "The start date for the consumption history (YYYY-MM-DD format).", "schema": {"type": "string", "format": "date"}}, {"name": "endDate", "in": "query", "required": true, "description": "The end date for the consumption history (YYYY-MM-DD format).", "schema": {"type": "string", "format": "date"}}], "responses": {"200": {"description": "Success response with consumption history data", "content": {"application/json": {"example": {"electricity": [{"date": "2023-09-01", "consumption": 15.5}, {"date": "2023-09-02", "consumption": 16.0}], "gas": [{"date": "2023-09-01", "consumption": 8.3}, {"date": "2023-09-02", "consumption": 7.9}], "water": [{"date": "2023-09-01", "consumption": 10.2}, {"date": "2023-09-02", "consumption": 11.0}]}}}}}}

Endpoint: POST /bills/pay
Specification:
{"summary": "Submit Payment for a Bill", "description": "Submit payment for an outstanding utility bill, providing payment details.", "requestBody": {"description": "Details of the bill payment including the bill ID and payment method.", "required": true, "content": {"application/json": {"example": {"billId": "98765", "paymentAmount": 75.5, "paymentMethod": "credit_card"}}}}, "responses": {"200": {"description": "Success response after processing the payment."}}}

Endpoint: POST /tenant/identity-verification
Specification:
{"summary": "Initiate identity verification for a tenant", "description": "Start the process of verifying the identity of a prospective tenant using their provided identification information.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"tenantId": {"type": "string", "description": "The unique identifier for the tenant."}, "firstName": {"type": "string", "description": "The tenant's first name."}, "lastName": {"type": "string", "description": "The tenant's last name."}, "dateOfBirth": {"type": "string", "format": "date", "description": "The tenant's date of birth in YYYY-MM-DD format."}, "identificationNumber": {"type": "string", "description": "The tenant's identification (e.g., driver's license or passport number)."}}, "required": ["tenantId", "firstName", "lastName", "dateOfBirth", "identificationNumber"]}}}}, "responses": {"201": {"description": "Identity verification request successfully initiated."}, "400": {"description": "Invalid input data provided."}}}

Endpoint: POST /properties/{property_id}/photos
Specification:
{"summary": "Upload Property Photos", "description": "Upload high-resolution photos for a specific property advertisement.", "parameters": [{"name": "property_id", "in": "path", "required": true, "description": "Unique identifier of the property.", "schema": {"type": "string"}}], "requestBody": {"required": true, "content": {"multipart/form-data": {"schema": {"type": "object", "properties": {"photo": {"type": "string", "format": "binary", "description": "High-resolution photo file."}}}}}}, "responses": {"201": {"description": "Photo uploaded successfully."}}}

Endpoint: POST /tenant/rental-history
Specification:
{"summary": "Submit rental history check for a tenant", "description": "Request to validate and retrieve the past rental history of a prospective tenant.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"tenantId": {"type": "string", "description": "The unique identifier for the tenant."}, "landlordContactInfo": {"type": "string", "description": "Contact information of prior landlords for validation."}}, "required": ["tenantId", "landlordContactInfo"]}}}}, "responses": {"201": {"description": "Rental history validation request successfully created."}, "400": {"description": "Invalid input data provided."}}}

Endpoint: GET /tenant/identity-verification/status/{tenantId}
Specification:
{"summary": "Retrieve tenant identity verification status", "description": "Fetch the current status and results of a previously requested identity verification for a specific tenant.", "parameters": [{"name": "tenantId", "in": "path", "required": true, "schema": {"type": "string"}, "description": "The unique identifier for the tenant."}], "responses": {"200": {"description": "Identity verification status retrieved successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"status": {"type": "string", "enum": ["Pending", "Completed", "Failed"], "description": "The status of the identity verification request."}, "verificationDate": {"type": "string", "format": "date-time", "description": "The date and time when the verification was completed, if applicable."}}}}}}, "404": {"description": "Tenant not found or no identity verification request exists."}}}

Endpoint: POST /tenant/credit-check
Specification:
{"summary": "Request a credit check for a tenant", "description": "Initiate a credit check for a prospective tenant, based on their financial history.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"tenantId": {"type": "string", "description": "The unique identifier for the tenant."}, "ssn": {"type": "string", "description": "Social Security Number of the tenant."}}, "required": ["tenantId", "ssn"]}}}}, "responses": {"201": {"description": "Credit check successfully requested."}, "400": {"description": "Invalid input data provided."}}}

Endpoint: GET /tenant/rental-history/{tenantId}
Specification:
{"summary": "Retrieve tenant rental history", "description": "Access the verified rental history information of a specific tenant.", "parameters": [{"name": "tenantId", "in": "path", "required": true, "schema": {"type": "string"}, "description": "The unique identifier for the tenant."}], "responses": {"200": {"description": "Rental history retrieved successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"rentalHistory": {"type": "array", "items": {"type": "object", "properties": {"propertyAddress": {"type": "string", "description": "Address of the rented property."}, "duration": {"type": "string", "description": "Duration of the tenant's stay at the property."}, "landlordContact": {"type": "string", "description": "Contact details of the landlord."}}}}}}}}}, "404": {"description": "Tenant not found or no rental history available."}}}

Endpoint: POST /properties/{property_id}/documents
Specification:
{"summary": "Upload Property Documents", "description": "Attach legal or promotional documents to a property advertisement.", "parameters": [{"name": "property_id", "in": "path", "required": true, "description": "Unique identifier of the property.", "schema": {"type": "string"}}], "requestBody": {"required": true, "content": {"multipart/form-data": {"schema": {"type": "object", "properties": {"document": {"type": "string", "format": "binary", "description": "Document file."}}}}}}, "responses": {"201": {"description": "Document uploaded successfully."}}}

Endpoint: GET /tenant/credit-check/status/{tenantId}
Specification:
{"summary": "Retrieve tenant credit check status", "description": "Obtain the status and outcomes of a completed credit check for a specific tenant.", "parameters": [{"name": "tenantId", "in": "path", "required": true, "schema": {"type": "string"}, "description": "The unique identifier for the tenant."}], "responses": {"200": {"description": "Credit check status retrieved successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"status": {"type": "string", "enum": ["Pending", "Completed", "Failed"], "description": "The status of the credit check."}, "creditScore": {"type": "integer", "description": "The tenant's credit score, if applicable."}}}}}}, "404": {"description": "Tenant not found or no credit check exists."}}}

Endpoint: PUT /settings/notifications
Specification:
{"summary": "Set notification preferences", "description": "Configure preferences to receive notifications for updates on identity, credit, or rental history verification checks.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"emailNotifications": {"type": "boolean", "description": "Enable or disable email notifications."}, "smsNotifications": {"type": "boolean", "description": "Enable or disable SMS notifications."}}, "required": ["emailNotifications", "smsNotifications"]}}}}, "responses": {"200": {"description": "Notification preferences updated successfully."}}}

Endpoint: DELETE /properties/{property_id}/photos/{photo_id}
Specification:
{"summary": "Delete Property Photo", "description": "Delete a specific photo from a property advertisement.", "parameters": [{"name": "property_id", "in": "path", "required": true, "description": "Unique identifier of the property.", "schema": {"type": "string"}}, {"name": "photo_id", "in": "path", "required": true, "description": "Unique identifier of the photo.", "schema": {"type": "string"}}], "responses": {"204": {"description": "Photo deleted successfully."}, "404": {"description": "Photo or property not found."}}}
